from pathlib import Path
import hashlib,json,base64
r=Path('/workspace/Java-portfolio/projects/07-indexforge/fixtures');r.mkdir(exist_ok=True)
topics=[('commitGeneration','atomic generation publication','Publish a fully committed search generation using an atomic filesystem pointer'),('acquireLease','reference counted reader lease','Keep a retired search reader alive while requests hold a generation lease'),('validateCursor','signed pagination validation','Reject pagination tokens whose tenant query generation or expiration differs'),('splitIdentifier','camel case identifier tokens','Split camel case acronyms and underscores while preserving source offsets'),('readSnapshot','bounded source directory ingestion','Read only configured local source roots and reject symbolic links'),('expandArchive','archive expansion limit','Bound compressed source archives by entry count expanded bytes and ratio'),('resumeCheckpoint','resumable ingestion checkpoint','Resume an interrupted ingestion from immutable manifest and checkpoint hints'),('hashContent','content addressed deduplication','Store UTF8 source bytes by SHA256 digest and verify existing content'),('authorizeRepository','repository authorization filter','Filter repositories before retrieval counts facets snippets and suggestions'),('revokePrincipal','authorization version recheck','Discard response when a principal permission version changes during search'),('buildQueryPlan','bounded boolean query parsing','Parse boolean operators phrases and field expressions with a depth bound'),('rankCandidates','deterministic relevance ranking','Combine content identifiers and paths with stable score ties'),('createSnippet','source line excerpt','Show a bounded source excerpt around matching text preserving original characters'),('verifyCommit','committed index integrity','Validate document counts source hashes schema and manifest before publication'),('recoverPointer','startup pointer recovery','Recover the last valid generation after corrupt pointer or unfinished staging'),('cancelIngestion','cooperative ingestion cancellation','Stop a bounded ingestion safely without changing the searchable generation'),('registerJob','idempotent ingestion registration','Reuse a job for identical manifest and reject changed content under one key'),('deleteSource','explicit snapshot deletion','Remove precisely the listed source paths and preserve partial upload documents'),('recordArtifact','versioned artifact coordinates','Search immutable artifact group name version digest and associated documentation'),('warmReader','committed search reader warmup','Open a committed reader and warm retrieval before atomic publication'),('calculateNdcg','graded ranking evaluation','Compute normalized discounted cumulative gain using graded relevance judgments'),('calculateMrr','first relevant reciprocal rank','Measure reciprocal rank of first relevant result within ten results'),('calculateRecall','relevant document recall','Measure how many judged relevant documents appear in the first twenty results'),('retireGeneration','deferred generation retirement','Close obsolete readers after outstanding leases finish then reclaim old files'),('validateUtf8','malformed source encoding','Reject malformed UTF8 rather than silently replacing invalid source bytes'),('enforceQuota','bounded request admission','Reject excessive requests and oversized bodies before decoding request content'),('verifyJwt','OIDC token validation','Verify issuer audience expiry signature subject scopes and tenant claims'),('aggregateFacets','authorized repository facets','Count matching repositories using the same authorized generation query'),('suggestSymbol','authorized identifier suggestions','Return source identifier completions only from permitted repositories'),('explainScore','authorized ranking explanation','Explain field weighted BM25 scores without exposing inaccessible source'),('syncMetadata','durable filesystem metadata','Force written files and containing directories before reporting publication'),('normalizePath','canonical relative source paths','Reject absolute parent traversal drive letter and noncanonical path inputs'),('detectDiskFull','storage exhaustion recovery','Fail writes explicitly when disk capacity is exhausted preserving old search state'),('replaceSnapshot','concurrent snapshot replacement','Serve an old or complete new snapshot while replacing source under load'),('verifyDigest','stored content corruption detection','Detect changes in content addressed files by comparing SHA256 digests'),('bindCursor','principal bound continuation','Bind continuation to principal permission version tenant query and generation'),('limitQueue','ingestion worker backpressure','Bound job queues and return overload when no worker capacity remains'),('searchPhrase','ordered phrase retrieval','Match ordered phrase tokens through a bounded typed query expression'),('filterLanguage','typed language filtering','Restrict result language and artifact kind before candidate selection'),('measureLatency','open loop latency measurement','Issue fixed rate search requests with scheduled arrival timestamps including queue delay')]
corpus=[];queries=[]
for i,(sym,topic,desc) in enumerate(topics):
 base=f'topic{i:02d}';ids=[base+'/Implementation.java',base+'/Guide.md',base+'/ContractTest.java',base+'/Notes.md']
 content=[f'/** {desc}. Engineering topic: {topic}. */\npublic final class Topic{i} {{ public void {sym}() {{ /* {topic} */ }} }}\n',f'# {topic}\n{desc}. This guide explains {sym} and its operational guarantees with explicit failure handling.\n',f'// Regression contract for {sym}: {desc}.\nclass Topic{i}ContractTest {{ void verifies{sym[0].upper()+sym[1:]}() {{}} }}\n',f'# Maintenance note {i}\nTopic{i} has a separate development lifecycle and a source revision.\n']
 for j in range(4):corpus.append({'path':ids[j],'symbol':sym if j<2 else f'verifies{sym[0].upper()+sym[1:]}' if j==2 else f'note{i}','content':content[j]})
 split='development' if i<20 else 'validation' if i<30 else 'held-out'
 for kind,text,grades in [('identifier',sym,{ids[0]:3,ids[1]:2,ids[2]:1}),('prose',topic,{ids[1]:3,ids[0]:2,ids[2]:1})]:
  queries.append({'id':f'q{len(queries)+1:02d}','split':split,'type':kind,'text':text,'grades':grades,'rationale':f'Authored {topic} topic: '+('exact implementation is primary; explanatory guide is secondary; regression contract is supporting evidence.' if kind=='identifier' else 'explanatory guide directly describes requested behavior; implementation and regression contract supply supporting evidence.')})
corpusbytes=''.join(json.dumps(d,ensure_ascii=False,sort_keys=True)+'\n' for d in corpus).encode();qbytes=''.join(json.dumps(d,ensure_ascii=False,sort_keys=True)+'\n' for d in queries).encode()
(r/'corpus.jsonl').write_bytes(corpusbytes);(r/'judgments.jsonl').write_bytes(qbytes)
(r/'FREEZE.json').write_text(json.dumps({'schemaVersion':1,'phase':'preregistered before any ranking measurement','corpusSha256':hashlib.sha256(corpusbytes).hexdigest(),'judgmentsSha256':hashlib.sha256(qbytes).hexdigest(),'queries':80,'split':{'development':40,'validation':20,'held-out':20},'independentReview':'REQUESTED; not yet approved','tuningPolicy':'Labels and split immutable. Compare predeclared BM25-content/source-aware/no-identifiers/no-path; select only on development and validation. Held-out opened once after selection. Retain baseline if held-out candidate does not improve.'},indent=2)+'\n')
# TSV consumed by dependency-free evaluation, frozen against same content.
(r/'corpus.tsv').write_text(''.join(d['path']+'\t'+d['symbol']+'\t'+base64.b64encode(d['content'].encode()).decode()+'\n' for d in corpus))
(r/'judgments.tsv').write_text(''.join(d['id']+'\t'+d['split']+'\t'+d['type']+'\t'+d['text']+'\t'+','.join(p+':'+str(g) for p,g in d['grades'].items())+'\n' for d in queries))
